            i.incrementAndGet();
        }
    }));
    assertEquals(1, i.get());
    verify(conn).setAutoCommit(false);
    verify(conn, times(1)).commit();
    verify(conn, times(0)).rollback();
    verify(conn, times(1)).close();
}

